async function exportQuestionCard(title:string,subtitle:string,question:string,options:string[]=[]){
 const canvas=document.createElement("canvas");
 const width=1200,pad=82,lineHeight=62;
 canvas.width=width;
 const ctx=canvas.getContext("2d");
 if(!ctx)throw new Error("Image export is not supported by this browser.");
 ctx.font="500 43px system-ui, sans-serif";
 const wrap=(value:string,maxWidth:number)=>{const lines:string[]=[];for(const paragraph of value.split(/\n/)){const words=paragraph.split(/\s+/).filter(Boolean);let line="";for(const word of words){const next=line?line+" "+word:word;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line);line=word}else line=next}if(line)lines.push(line);if(!words.length)lines.push("")}return lines};
 const questionLines=wrap(question,width-pad*2);
 const optionLines=options.map(option=>wrap(option,width-pad*2-76));
 const optionHeight=optionLines.reduce((sum,lines)=>sum+Math.max(1,lines.length)*51+34,0);
 const height=310+questionLines.length*lineHeight+(options.length?58+optionHeight:0)+130;
 canvas.height=height;
 const draw=canvas.getContext("2d");
 if(!draw)throw new Error("Image export is not supported by this browser.");
 const background=draw.createLinearGradient(0,0,width,height);background.addColorStop(0,"#111827");background.addColorStop(1,"#172a46");
 draw.fillStyle=background;draw.fillRect(0,0,width,height);
 draw.fillStyle="#6d9cff";draw.fillRect(pad,76,12,62);
 draw.fillStyle="#a9c5ff";draw.font="700 27px system-ui, sans-serif";draw.fillText("ACE STUDENT",pad+34,116);
 draw.fillStyle="#d8e2f4";draw.font="500 25px system-ui, sans-serif";draw.fillText(subtitle.slice(0,75),pad,190);
 draw.fillStyle="#ffffff";draw.font="700 47px system-ui, sans-serif";draw.fillText(title.slice(0,70),pad,258);
 draw.fillStyle="#e6edf8";draw.font="500 43px system-ui, sans-serif";
 let y=330;
 for(const line of questionLines){draw.fillText(line,pad,y);y+=lineHeight}
 if(options.length){y+=22;draw.fillStyle="#a9c5ff";draw.font="700 24px system-ui, sans-serif";draw.fillText("ANSWER OPTIONS",pad,y);y+=45;
  draw.font="500 33px system-ui, sans-serif";draw.fillStyle="#e6edf8";
  optionLines.forEach((lines,index)=>{draw.fillStyle="#6d9cff";draw.font="700 29px system-ui, sans-serif";draw.fillText(String.fromCharCode(65+index)+".",pad,y);draw.fillStyle="#e6edf8";draw.font="500 33px system-ui, sans-serif";for(const line of lines){draw.fillText(line,pad+68,y);y+=51}y+=28})
 }
 draw.fillStyle="#9fb2d1";draw.font="500 22px system-ui, sans-serif";draw.fillText("Study together · ace student",pad,height-54);
 const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error("Could not create the image.")),"image/png"));
 const filename="ace-student-question.png";
 try{
  const file=new File([blob],filename,{type:"image/png"});
  if(typeof navigator.share==="function"&&typeof navigator.canShare==="function"&&navigator.canShare({files:[file]})){
   try{await navigator.share({files:[file],title:"Ace Student question"});return}catch(error){if(error instanceof DOMException&&error.name==="AbortError")return}
  }
 }catch{}
 const url=URL.createObjectURL(blob);
 const anchor=document.createElement("a");anchor.href=url;anchor.download=filename;document.body.appendChild(anchor);anchor.click();anchor.remove();
 window.setTimeout(()=>URL.revokeObjectURL(url),1000);
}

