 const[resources,setResources]=useState<OpenResource[]>([]),[busy,setBusy]=useState(true),[issue,setIssue]=useState(""),[filter,setFilter]=useState("All"),[saved,setSaved]=useState<string[]>([]),[savedOnly,setSavedOnly]=useState(false);
 async function loadOpenResources(){if(!supabase){setIssue("The resource service is not configured.");setBusy(false);return}setBusy(true);setIssue("");const controller=new AbortController();const timeout=window.setTimeout(()=>controller.abort(),8000);try{const{data,error}=await supabase.from("ace_open_resources").select("*").eq("hidden",false).order("title").abortSignal(controller.signal);if(error)throw error;setResources(data??[])}catch{setIssue("Open learning resources could not be reached. Check your connection and retry.");}finally{window.clearTimeout(timeout);setBusy(false)}}
