  async function copyQuizQuestion(question:Question){const prompt="You are my BBA study tutor. Explain the concept being tested, show a clear reasoning process, and then ask me one follow-up question. Do not claim this is an official model answer.\n\nUnit: "+(chosen?.course_code??courseCode??"BBA")+"\nQuiz: "+(chosen?.title??"Practice question")+"\nQuestion: "+question.prompt+"\nOptions:\n"+question.options.map((option,index)=>String.fromCharCode(65+index)+". "+option).join("\n");try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(prompt);setIssue("AI tutoring prompt copied.")}else{window.prompt("Copy this tutoring prompt",prompt)}}catch{window.prompt("Copy this tutoring prompt",prompt)}}
