 async function load(){if(!supabase)return;const{data,error}=await supabase.from("ace_resources").select("id,title,course_code,course_name,kind,status,review_note,storage_path,created_at").eq("uploader_id",user.id).order("created_at",{ascending:false}).limit(80);if(error)setIssue("Could not load submissions.");else setItems(data??[])}
