 async function withdraw(item:Submission){if(!supabase||item.status!=="pending")return;if(!window.confirm("Withdraw this pending document? This cannot be undone."))return;setBusy(true);setIssue("");const{error}=await supabase.from("ace_resources").delete().eq("id",item.id).eq("uploader_id",user.id).eq("status","pending");if(error){setIssue(error.message);setBusy(false);return}const clean=await supabase.storage.from("ace-submissions").remove([item.storage_path]);if(clean.error)setIssue("Withdrawn, but stored-file cleanup needs attention.");await load();setBusy(false)}
 if(!items.length)return null;
